</head>
<body>

  <div class="header">
    <h1>End-to-End ML Infrastructure Pipeline</h1>
    <p>Directed architecture with data lineage, online/offline branching, and observability feedback loops.</p>
  </div>

  <div class="legend">
    <div class="legend-group">
      <h4>Layers</h4>
      <div class="legend-item"><div class="legend-color" style="background: var(--layer-data)"></div>Data Layer</div>
      <div class="legend-item"><div class="legend-color" style="background: var(--layer-compute)"></div>Compute Layer</div>
      <div class="legend-item"><div class="legend-color" style="background: var(--layer-serving)"></div>Serving Layer</div>
      <div class="legend-item"><div class="legend-color" style="background: var(--layer-observability)"></div>Observability Layer</div>
    </div>
    <div class="legend-group">
      <h4>Flow Types</h4>
      <div class="legend-item"><div class="legend-line" style="background: #94a3b8"></div>Primary Data Flow</div>
      <div class="legend-item"><div class="legend-line" style="background: #8b5cf6; border-top: 2px dashed #000;"></div>Data Lineage</div>
      <div class="legend-item"><div class="legend-line" style="background: #ef4444; border-top: 2px dashed #000;"></div>Feedback Loop</div>
    </div>
    <div class="legend-group">
      <h4>Encoding</h4>
      <div class="legend-item">Node Size = Criticality Score</div>
      <div class="legend-item">Edge Thickness = Throughput</div>
    </div>
  </div>

  <svg width="1920" height="1080" id="edges-svg" style="position:absolute; top:0; left:0; z-index:0;">
    <defs>
      <marker id="arrow-primary" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse">
        <path d="M 0 0 L 10 5 L 0 10 z" fill="#94a3b8" />
      </marker>
      <marker id="arrow-lineage" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse">
        <path d="M 0 0 L 10 5 L 0 10 z" fill="#8b5cf6" />
      </marker>
      <marker id="arrow-feedback" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse">
        <path d="M 0 0 L 10 5 L 0 10 z" fill="#ef4444" />
      </marker>
      <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
        <feDropShadow dx="0" dy="2" stdDeviation="3" flood-opacity="0.5"/>
      </filter>
    </defs>
    <g id="edge-group"></g>
  </svg>

  <div id="nodes-container"></div>

  <script>
    const nodeData = [
      { id: "data_platform", label: "Data Platform\n(Spark / Flink)", layer: "data", sub_components: ["Apache Spark", "Apache Flink", "Kafka Ingestion"], criticality: 9, category: "data-layer", x: 200, y: 480 },
      { id: "feature_store", label: "Feature Store", layer: "data", sub_components: ["Online Store (Redis)", "Offline Store (Hive)", "Feature Registry"], criticality: 8, category: "data-layer", x: 480, y: 480 },
      { id: "training_cluster", label: "Training Cluster\n(GPU)", layer: "compute", sub_components: ["NVIDIA A100 Pool", "Distributed Training (Horovod)", "Hyperparameter Tuning"], criticality: 10, category: "compute-layer", x: 760, y: 480 },
      { id: "model_registry", label: "Model Registry", layer: "compute", sub_components: ["MLflow Registry", "Model Versioning", "Artifact Storage (S3)"], criticality: 8, category: "compute-layer", x: 1040, y: 480 },
      { id: "inference_online", label: "Inference Service\n(Online / Real-time)", layer: "serving", sub_components: ["TensorRT", "Triton Server", "Load Balancer"], criticality: 9, category: "serving-layer", x: 1350, y: 300 },
      { id: "inference_offline", label: "Inference Service\n(Offline / Batch)", layer: "serving", sub_components: ["Spark Batch Predict", "Scheduled Jobs (Airflow)"], criticality: 7, category: "serving-layer", x: 1350, y: 660 },
      { id: "ab_experiment", label: "A/B Experiment\nPlatform", layer: "serving", sub_components: ["Traffic Splitting", "Statistical Engine", "Experiment Dashboard"], criticality: 8, category: "serving-layer", x: 1620, y: 480 },
      { id: "monitoring", label: "Monitoring &\nAlerting", layer: "observability", sub_components: ["Prometheus", "Grafana", "PagerDuty", "Data Drift Detector"], criticality: 9, category: "observability-layer", x: 1830, y: 480 },
      { id: "version_control", label: "Version Control\n& Data Lineage", layer: "cross-cutting", sub_components: ["DVC", "Git", "Lineage Graph DB"], criticality: 7, category: "observability-layer", x: 620, y: 820 }
    ];

    const edgeData = [
      { source: "data_platform", target: "feature_store", flow_type: "primary", throughput_gbps: 12.5, label: "Raw → Features" },
      { source: "feature_store", target: "training_cluster", flow_type: "primary", throughput_gbps: 8.0, label: "Training Data" },
      { source: "training_cluster", target: "model_registry", flow_type: "primary", throughput_gbps: 2.5, label: "Trained Models" },
      { source: "model_registry", target: "inference_online", flow_type: "primary", throughput_gbps: 1.8, label: "Model Deploy (Online)" },
      { source: "model_registry", target: "inference_offline", flow_type: "primary", throughput_gbps: 3.2, label: "Model Deploy (Batch)" },
      { source: "inference_online", target: "ab_experiment", flow_type: "primary", throughput_gbps: 5.0, label: "Predictions (RT)" },
      { source: "inference_offline", target: "ab_experiment", flow_type: "primary", throughput_gbps: 4.0, label: "Predictions (Batch)" },
      { source: "ab_experiment", target: "monitoring", flow_type: "primary", throughput_gbps: 2.0, label: "Metrics & Results" },
      { source: "monitoring", target: "data_platform", flow_type: "feedback", throughput_gbps: 0.5, label: "Data Quality Alerts" },
      { source: "monitoring", target: "training_cluster", flow_type: "feedback", throughput_gbps: 0.3, label: "Retrain Trigger" },
      { source: "version_control", target: "feature_store", flow_type: "lineage", throughput_gbps: 0.1, label: "Feature Versioning" },
      { source: "version_control", target: "training_cluster", flow_type: "lineage", throughput_gbps: 0.1, label: "Experiment Tracking" },
      { source: "version_control", target: "model_registry", flow_type: "lineage", throughput_gbps: 0.1, label: "Model Lineage" },
      { source: "data_platform", target: "version_control", flow_type: "lineage", throughput_gbps: 0.2, label: "Data Lineage" },
      { source: "feature_store", target: "inference_online", flow_type: "primary", throughput_gbps: 6.0, label: "Online Features" }
    ];

    const colorMap = {
      'data-layer': 'var(--layer-data)',
      'compute-layer': 'var(--layer-compute)',
      'serving-layer': 'var(--layer-serving)',
      'observability-layer': 'var(--layer-observability)'
    };

    // Render Nodes
    const nodesHtml = nodeData.map(node => {
      node.scale = 1 + (node.criticality - 8) * 0.15;
      let color = colorMap[node.category];
      let subItems = node.sub_components.map(sub => `<li>${sub}</li>`).join('');
      let labelHtml = node.label.replace('\n', '<br>');

      return `
        <div id="${node.id}" class="node" style="left: ${node.x}px; top: ${node.y}px; transform: translate(-50%, -50%) scale(${node.scale}); border-color: ${color};">
          <div class="node-header" style="background: ${color};">
            ${labelHtml}
          </div>
          <div class="node-body">
            <ul>${subItems}</ul>
            <div class="node-meta" style="color: ${color}">Crit: ${node.criticality} / 10</div>
          </div>
        </div>
      `;
    }).join('');
    document.getElementById('nodes-container').innerHTML = nodesHtml;

    // Helper functions for edges
    function getEdgePoints(sNode, tNode) {
      let sx = sNode.x, sy = sNode.y;
      let tx = tNode.x, ty = tNode.y;

      let sw = 180 * sNode.scale, sh = 120 * sNode.scale;
      let tw = 180 * tNode.scale, th = 120 * tNode.scale;

      let endX = tx, endY = ty;
      let startX = sx, startY = sy;

      if (Math.abs(tx - sx) > Math.abs(ty - sy)) {
        if (tx > sx) { endX = tx - tw/2 - 8; startX = sx + sw/2; } 
        else { endX = tx + tw/2 + 8; startX = sx - sw/2; }
      } else {
        if (ty > sy) { endY = ty - th/2 - 8; startY = sy + sh/2; } 
        else { endY = ty + th/2 + 8; startY = sy - sh/2; }
      }

      // Custom tweaks
      if (sNode.id === 'monitoring' && tNode.id === 'data_platform') {
        startX = sx; startY = sy + sh/2; endX = tx; endY = ty + th/2 + 8;
      }
      if (sNode.id === 'monitoring' && tNode.id === 'training_cluster') {
        startX = sx; startY = sy + sh/2; endX = tx; endY = ty + th/2 + 8;
      }
      if (sNode.id === 'data_platform' && tNode.id === 'version_control') {
        startX = sx; startY = sy + sh/2; endX = tx - tw/2 - 8; endY = ty;
      }

      return { startX, startY, endX, endY };
    }

    function getPath(sNode, tNode, startX, startY, endX, endY, flow_type) {
      if (flow_type === 'feedback') {
        let cx1 = startX, cy1 = startY + 400;
        let cx2 = endX, cy2 = endY + 400;
        return `M ${startX} ${startY} C ${cx1} ${cy1}, ${cx2} ${cy2}, ${endX} ${endY}`;
      }
      if (flow_type === 'lineage') {
        if (sNode.id === 'data_platform' && tNode.id === 'version_control') {
           return `M ${startX} ${startY} C ${startX} ${startY + 100}, ${endX - 100} ${endY}, ${endX} ${endY}`;
        }
        let cx1 = startX, cy1 = startY - 150;
        let cx2 = endX, cy2 = endY + 150;
        return `M ${startX} ${startY} C ${cx1} ${cy1}, ${cx2} ${cy2}, ${endX} ${endY}`;
      }
      if (sNode.id === 'feature_store' && tNode.id === 'inference_online') {
        let cx1 = startX + 250, cy1 = startY - 350;
        let cx2 = endX - 250, cy2 = endY - 350;
        return `M ${startX} ${startY} C ${cx1} ${cy1}, ${cx2} ${cy2}, ${endX} ${endY}`;
      }

      let cx1 = startX + (endX - startX)*0.5;
      let cx2 = cx1;
      return `M ${startX} ${startY} C ${cx1} ${startY}, ${cx2} ${endY}, ${endX} ${endY}`;
    }

    // Render Edges
    let edgeHtml = '';
    edgeData.forEach((edge, i) => {
      let sNode = nodeData.find(n => n.id === edge.source);
      let tNode = nodeData.find(n => n.id === edge.target);

      let { startX, startY, endX, endY } = getEdgePoints(sNode, tNode);
      let pathD = getPath(sNode, tNode, startX, startY, endX, endY, edge.flow_type);

      let thickness = 1 + Math.sqrt(edge.throughput_gbps) * 1.5;
      let strokeColor = '#94a3b8';
      let dashArray = 'none';
      let marker = 'url(#arrow-primary)';

      if (edge.flow_type === 'lineage') {
        strokeColor = '#8b5cf6';
        dashArray = '6,4';
        marker = 'url(#arrow-lineage)';
      } else if (edge.flow_type === 'feedback') {
        strokeColor = '#ef4444';
        dashArray = '8,4';
        marker = 'url(#arrow-feedback)';
      }

      let pathId = `path-${i}`;

      // We render a transparent wide path first to ensure text follows it nicely
      edgeHtml += `
        <path d="${pathD}" fill="none" stroke="transparent" stroke-width="20" id="${pathId}" />
        <path d="${pathD}" fill="none" stroke="${strokeColor}" stroke-width="${thickness}" stroke-dasharray="${dashArray}" marker-end="${marker}" filter="url(#shadow)" />
        <text font-size="12" font-weight="600" fill="#cbd5e1" dy="-8">
          <textPath href="#${pathId}" startOffset="50%" text-anchor="middle">${edge.label} (${edge.throughput_gbps}Gbps)</textPath>
        </text>
      `;
    });

    document.getElementById('edge-group').innerHTML = edgeHtml;
  </script>
</body>
</html>
EOF

